/*!
 * Themeasy — Elementor Preview
 *
 * Central runtime for Themeasy scripts inside the Elementor preview iframe.
 *
 * Architecture:
 * - Single boot (no repeated elementor/frontend/init blocks)
 * - Widget registry via themeasy.PreviewRuntime.register()
 * - Raw hook registry via themeasy.PreviewRuntime.registerHook()
 * - Handlers run on every Elementor re-render (element_ready)
 * - Per-handler isolation (one widget error won't break others)
 * - Optional per-scope guard: once($scope, key, fn)
 * - Debug logger available (disabled by default)
 *
 * Register a widget below ONLY for behavior the markup cannot describe.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document, $) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}

  // Prevent double-loading.
  if (window.Themeasy.PreviewRuntime) {
    return
  }

  /* ========================================================================
   * Preview Runtime (PUBLIC)
   * Widget registration and binding system for Elementor preview.
   * ======================================================================== */

  const PreviewRuntime = (function () {

    // Internal state.
    const registry    = new Map()
    const rawRegistry = new Map()
    const onceGuards  = new WeakMap()

    let isBound = false

    // Debug is disabled by default (keep editor fast).
    // Enable manually in DevTools: window.Themeasy.PreviewRuntime.setDebug(true)
    let debugEnabled = false

    // ------------------------------------------------------------------------
    // Internal helpers.
    // ------------------------------------------------------------------------
    function hasElementorHooks() {
      return !!(window.elementorFrontend && window.elementorFrontend.hooks)
    }

    function log() {
      if (!debugEnabled) return

      console.log.apply(console, arguments)
    }

    function warn() {
      if (!debugEnabled) return

      console.warn.apply(console, arguments)
    }

    function getScopeEl($scope) {
      return $scope && $scope[0] ? $scope[0] : null
    }

    /**
     * Run a callback once per widget scope element + key.
     *
     * NOTE: Do NOT wrap the entire widget handler with once() if you need
     * Elementor live updates to re-run animations/re-calculations.
     *
     * @param {jQuery} $scope Elementor widget scope.
     * @param {string} key Guard key.
     * @param {Function} fn Callback to run once.
     */
    function once($scope, key, fn) {
      const el = getScopeEl($scope)
      if (!el || !key || typeof fn !== 'function') return

      let set = onceGuards.get(el)
      if (!set) {
        set = new Set()
        onceGuards.set(el, set)
      }

      const guardKey = String(key)

      if (set.has(guardKey)) return
      set.add(guardKey)

      fn()
    }

    /**
     * Execute handler safely. One widget error should not break others.
     *
     * @param {string} widgetName Widget name.
     * @param {Function} handler Handler.
     * @param {jQuery} $scope Scope.
     */
    function safeRun(widgetName, handler, $scope) {
      try {
        handler($scope, $, api)

      } catch (err) {
        // Keep editor usable even if a widget throws.
        warn('[Themeasy PreviewRuntime] Handler error:', widgetName, err)
      }
    }

    /**
     * Bind a single widget handler to Elementor hook.
     *
     * @param {string} widgetName Widget name.
     * @param {Function} handler Handler.
     */
    function bindWidget(widgetName, handler) {
      if (!hasElementorHooks()) return

      window.elementorFrontend.hooks.addAction(
        `frontend/element_ready/${widgetName}.default`,
        function ($scope) {
          safeRun(widgetName, handler, $scope)
        }
      )

      log('[Themeasy PreviewRuntime] Bound:', widgetName)
    }

    /**
     * Bind a raw hook handler to Elementor hook.
     *
     * @param {string} hookName Hook name.
     * @param {Function} handler Handler.
     */
    function bindRawHook(hookName, handler) {
      if (!hasElementorHooks()) return

      window.elementorFrontend.hooks.addAction(hookName, function ($scope) {
        safeRun(hookName, handler, $scope)
      })

      log('[Themeasy PreviewRuntime] Bound hook:', hookName)
    }

    /**
     * Bind all registered widgets (only once).
     */
    function bindAll() {
      if (isBound) return
      if (!hasElementorHooks()) return

      isBound = true

      registry.forEach((handler, widgetName) => {
        bindWidget(widgetName, handler)
      })

      rawRegistry.forEach((handler, hookName) => {
        bindRawHook(hookName, handler)
      })

      log('[Themeasy PreviewRuntime] Bound all widgets:', registry.size)
    }

    // ------------------------------------------------------------------------
    // Public API.
    // ------------------------------------------------------------------------
    function register(widgetName, handler) {
      if (!widgetName || typeof handler !== 'function') return

      const key = String(widgetName).trim()
      if (!key) return

      // Replace if exists (allows overriding/patching).
      registry.set(key, handler)

      // Late registration safe: if runtime is already bound, bind immediately.
      if (isBound && hasElementorHooks()) {
        bindWidget(key, handler)
      }

      log('[Themeasy PreviewRuntime] Registered:', key)
    }

    function registerHook(hookName, handler) {
      if (!hookName || typeof handler !== 'function') return

      const key = String(hookName).trim()
      if (!key) return

      // Store separately or reuse same registry (optional). Simple approach:
      rawRegistry.set(key, handler)

      // Late registration safe: if runtime is already bound, bind immediately.
      if (isBound && hasElementorHooks()) {
        bindRawHook(key, handler)
      }

      log('[Themeasy PreviewRuntime] Registered hook:', key)
    }

    function init() {
      // Normal path: Elementor triggers this event.
      $(window).on('elementor/frontend/init', function () {
        bindAll()
      })

      // Fallback: if Elementor hooks already exist, the init event might have fired
      // before this script loaded (timing edge cases). Bind on next tick.
      if (hasElementorHooks()) {
        window.setTimeout(bindAll, 0)
      }
    }

    function setDebug(state) {
      debugEnabled = !!state
      log('[Themeasy PreviewRuntime] Debug:', debugEnabled)
    }

    const api = {
      init,
      register,
      registerHook,
      once,
      setDebug
    }

    return api
  })()

  window.Themeasy.PreviewRuntime = PreviewRuntime
  window.Themeasy.PreviewRuntime.init()

  /* ------------------------------------------------------------------------
   * 18. Pricing Table
   * ------------------------------------------------------------------------ */
  window.Themeasy.PreviewRuntime.register('themeasy-pricing-table', function ($scope, $, api) {
    // The grid border is pure CSS (structural edges) — nothing to re-init here.
    const $priceToggles = $scope.find('.tms-price-toggle')
    if ($priceToggles.length) {
      window.Themeasy.pricingTable.init()
    }
  })

  /* ------------------------------------------------------------------------
   * 61. Video
   * ------------------------------------------------------------------------ */
  window.Themeasy.PreviewRuntime.register('themeasy-video', function ($scope, $, api) {
    const el = $scope && $scope[0] ? $scope[0] : null
    if (!el) return
    if (!el.querySelector('.tms-video')) return

    // The wrapper carries tms-video--static in the editor, so the frontend
    // init() skips the click-to-load wiring and only the safe parts run: the
    // auto YouTube poster's maxres -> hq fallback swap and the ambient loop's
    // reduced-motion pause, both needed again on every re-rendered DOM.
    // reset() first keeps it idempotent.
    if (window.Themeasy.video && window.Themeasy.video.reset) {
      window.Themeasy.video.reset(el)
    }
    if (window.Themeasy.video && window.Themeasy.video.init) {
      window.Themeasy.video.init(el)
    }
  })

})(window, document, jQuery)
